import mongoose, { Schema, Document, Model } from 'mongoose';

export const VALID_AVATARS = [
  'BIRD1', 'BIRD2', 'BIRD3', 'BIRD4', 'BIRD5', 'BIRD6',
  'BIRD7', 'BIRD8', 'BIRD9', 'BIRD10', 'BIRD11', 'BIRD12'
] as const;

export type BirdAvatar = typeof VALID_AVATARS[number];

export interface IDevice {
  deviceId: string;
  serialNumber: string;
  tokenHash: string;
  displayName: string;
  avatar: BirdAvatar;
  isSimulator: boolean;
  registeredAt: Date;
  lastSeen: Date;
  isActive: boolean;
  registrationIp?: string;
}

export interface IDeviceDocument extends IDevice, Document {}

const DeviceSchema = new Schema<IDeviceDocument>({
  deviceId: { 
    type: String, 
    required: true, 
    unique: true,
    index: true 
  },
  serialNumber: {
    type: String,
    required: true,
    unique: true,
    index: true
  },
  tokenHash: { 
    type: String, 
    required: true,
    index: true
  },
  displayName: { 
    type: String, 
    default: 'Unnamed Device' 
  },
  avatar: {
    type: String,
    enum: ['BIRD1', 'BIRD2', 'BIRD3', 'BIRD4', 'BIRD5', 'BIRD6', 'BIRD7', 'BIRD8', 'BIRD9', 'BIRD10', 'BIRD11', 'BIRD12'],
    default: 'BIRD1'
  },
  isSimulator: {
    type: Boolean,
    default: false
  },
  registeredAt: { 
    type: Date, 
    default: Date.now 
  },
  lastSeen: { 
    type: Date, 
    default: Date.now 
  },
  isActive: { 
    type: Boolean, 
    default: true,
    index: true
  },
  registrationIp: {
    type: String,
    default: null
  }
});

DeviceSchema.index({ tokenHash: 1, isActive: 1 });

export const Device: Model<IDeviceDocument> = mongoose.models.Device || mongoose.model<IDeviceDocument>('Device', DeviceSchema);
